-- Geography: the cities (service areas) SFF Taxi works in, with per-city tariff overrides.
-- Copied from SFF Eats (migrations/0007_geo.sql) with the same OSM-derived boundaries.
--
-- No PostGIS: a city's service area is a GeoJSON-like polygon in jsonb (rings of [lng, lat],
-- the first ring is the outer boundary, any further rings are holes). Its bounding box is
-- kept in plain columns so SQL can prefilter cheaply; the exact point-in-polygon test runs
-- in the API (src/lib/geo.ts). The polygon decides what is an in-city ride (fixed distance
-- bands) and what is a suburb or intercity ride (per km) — docs/architecture.md.

CREATE TABLE cities (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug             text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name_uz          text NOT NULL CHECK (char_length(name_uz) BETWEEN 1 AND 100),
  name_ru          text NOT NULL CHECK (char_length(name_ru) BETWEEN 1 AND 100),
  center_lat       double precision NOT NULL CHECK (center_lat BETWEEN -90 AND 90),
  center_lng       double precision NOT NULL CHECK (center_lng BETWEEN -180 AND 180),
  boundary         jsonb NOT NULL
                     CHECK (jsonb_typeof(boundary) = 'array' AND jsonb_array_length(boundary) >= 1),
  -- bounding box of the outer ring, maintained together with boundary
  min_lat          double precision NOT NULL,
  max_lat          double precision NOT NULL,
  min_lng          double precision NOT NULL,
  max_lng          double precision NOT NULL,
  timezone         text NOT NULL DEFAULT 'Asia/Tashkent',
  -- inactive cities are shown to riders as "coming soon": rides cannot start there
  -- (they can still be an intercity destination)
  is_active        boolean NOT NULL DEFAULT false,
  sort             int NOT NULL DEFAULT 0,
  -- the city's own tariff (same JSON shape as the global "tariff" setting); NULL = global
  tariff           jsonb,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  CHECK (min_lat <= max_lat AND min_lng <= max_lng)
);

-- Launch region: Sirdaryo viloyati. Guliston launches first; the other towns are listed
-- as upcoming (inactive) until rides start there.
--
-- Source: OpenStreetMap via Nominatim (https://nominatim.openstreetmap.org, data © OpenStreetMap
-- contributors, ODbL), retrieved 2026-09-26. Boundaries are the OSM town outlines, simplified
-- (Douglas–Peucker) to at most 40 points and rounded to 5 decimals (~1 m):
--   guliston    relation 8310445 "Guliston shahri" (city boundary); centre = place relation 11086478
--   yangiyer    relation 11086479 "Yangiyer shahri"; centre = place node 246154460
--   shirin      way 140375240;  sirdaryo way 482889158;  boyovut way 170084310 ("Bayaut")
--   baxt        way 182899829;  xovos way 131644629;  oqoltin way 197574548;  sardoba way 191900971
--   sayxunobod  way 142672631 "Sayhun" - the seat of Sayxunobod district
--   mirzaobod   node 1979037163 "Navro'z" - the seat of Mirzaobod district. OSM has only a point,
--               so the boundary is an APPROXIMATE 16-gon of radius 1.8 km around it; replace it
--               with a surveyed outline before launching there.
-- Centres of towns given as ways are the Nominatim centroids.
INSERT INTO cities (slug, name_uz, name_ru, center_lat, center_lng, is_active, sort, boundary,
                    min_lat, max_lat, min_lng, max_lng)
SELECT v.slug, v.name_uz, v.name_ru, v.center_lat, v.center_lng, v.is_active, v.sort,
